import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill } from '../remotionShim';


export type LiquidTopographyProps = Record<string, any>;

const LiquidTopography: React.FC<LiquidTopographyProps> = ({
  backgroundColor = "#F4F0EB",
  transparentBackground = false,
  durationInSeconds = 10,
  lineColor = "#CC3314",
  numberOfLines = 45,
  fluidity = 1.2,
  waveIntensity = 60,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Animation timing
  const durationInFrames = durationInSeconds * fps;
  const progress = (frame % durationInFrames) / durationInFrames;
  // Multiply by 2 * PI to create a seamless circular loop phase
  const phase = progress * Math.PI * 2;

  // Layout calculations
  const cx = width / 2;
  const cy = height / 2;
  // Responsive sizing based on canvas width
  const outerRadius = width * 0.42;
  const innerRadius = width * 0.24;

  // Extend the coverage area to ensure lines fill the entire outer circle
  // when rotated and distorted by the liquid effects
  const coverageArea = width * 1.3;
  const spacing = coverageArea / numberOfLines;
  const startY = -(coverageArea / 2);

  // Generate the liquid topographic paths
  const paths = Array.from({ length: numberOfLines }).map((_, i) => {
    const baseY = startY + i * spacing;
    let d = "";
    // Step size controls the smoothness of the curve (lower = smoother but more points)
    const step = 8;
    const halfSize = coverageArea / 2;

    for (let x = -halfSize; x <= halfSize; x += step) {
      // Normalize x and y for predictable sine wave behavior across different canvas sizes
      const nx = x / coverageArea;
      const ny = i / numberOfLines;

      // X displacement to create lateral liquid pooling and flowing
      let xOffset = Math.sin(ny * Math.PI * 4 + phase) * (waveIntensity * 0.5);
      xOffset += Math.cos(nx * Math.PI * 2 - phase) * (waveIntensity * 0.3);

      // Y displacement with multiple combined sine/cosine waves
      // Integer phase multipliers (e.g., phase, phase * 2) guarantee seamless looping
      
      // 1. Primary rolling wave (mostly parallel for the topographic look)
      let yOffset = Math.sin(nx * Math.PI * 2 * fluidity + phase + ny * Math.PI * 2) * waveIntensity;
      
      // 2. Secondary counter-wave for complexity and pinching
      yOffset += Math.cos(nx * Math.PI * 3 * fluidity - phase * 2 + ny * Math.PI * 3) * (waveIntensity * 0.5);
      
      // 3. Tertiary slow global sway
      yOffset += Math.sin(nx * Math.PI * 1.5 + phase + ny * Math.PI) * (waveIntensity * 0.7);

      const finalX = x + xOffset;
      const finalY = baseY + yOffset;

      if (x === -halfSize) {
        d += `M ${finalX} ${finalY}`;
      } else {
        d += ` L ${finalX} ${finalY}`;
      }
    }
    return d;
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, transition: "none" }}>
      <svg width={width} height={height} viewBox={`0 0 ${width} ${height}`}>
        <defs>
          {/* Mask to contain the wavy lines perfectly within the donut ring */}
          <mask id="donut-mask">
            <circle cx={cx} cy={cy} r={outerRadius} fill="white" />
            <circle cx={cx} cy={cy} r={innerRadius} fill="black" />
          </mask>
        </defs>

        {/* Liquid Lines Container */}
        <g mask="url(#donut-mask)">
          {/* Rotate the group slightly to give a dynamic diagonal flow to the liquid */}
          <g transform={`translate(${cx}, ${cy}) rotate(-35)`} style={{ transition: "none" }}>
            {paths.map((d, i) => (
              <path
                key={i}
                d={d}
                fill="none"
                stroke={lineColor}
                strokeWidth={2}
                strokeLinecap="round"
                strokeLinejoin="round"
                style={{ transition: "none" }}
              />
            ))}
          </g>
        </g>

        {/* Outer Minimal Circle */}
        <circle
          cx={cx}
          cy={cy}
          r={outerRadius}
          fill="none"
          stroke={lineColor}
          strokeWidth={3}
          style={{ transition: "none" }}
        />

        {/* Inner Circle Border */}
        <circle
          cx={cx}
          cy={cy}
          r={innerRadius}
          fill="none"
          stroke={lineColor}
          strokeWidth={3}
          style={{ transition: "none" }}
        />
      </svg>
    </AbsoluteFill>
  );
};

export default LiquidTopography;